import numpy as np
from scipy.optimize import least_squares
TSS=np.sum((dv_dt-dv_dt.mean())**2)
forms={
 'tanh': lambda p: p[1]+p[2]*np.tanh(p[3]*x)+p[4]*x+p[5]*v+p[6]*v*np.abs(v)+p[7]*x*v,
 'sin': lambda p: p[1]+p[2]*np.sin(p[3]*x)+p[4]*x+p[5]*v+p[6]*v*np.abs(v)+p[7]*x*v,
 'xexp': lambda p: p[1]+p[2]*x*np.exp(-p[3]*x)+p[4]*x+p[5]*v+p[6]*v*np.abs(v)+p[7]*x*v,
 'powx': lambda p: p[1]+p[2]*x**p[3]+p[4]*x+p[5]*v+p[6]*v*np.abs(v)+p[7]*x*v,
}
for nm,f in forms.items():
    best=None
